(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.015+t*0.3)*11;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sy*0.025+t*0.4)*8 + Math.cos(sx*0.02-t*0.35)*6;
  const w2y = Math.cos(sx*0.022+t*0.45)*7 + Math.sin(sy*0.018-t*0.38)*5;
  const dx = sx+w2x, dy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.075, 2.1, 0.8],
    [320+Math.cos(t*0.45)*105, 160+Math.sin(t*0.6)*55, 0.09, 1.8, 1.0],
    [240+Math.sin(t*0.28+2)*145, 120+Math.cos(t*0.42+1)*95, 0.055, 2.4, 0.6],
    [100+Math.cos(t*0.7+1)*85, 190+Math.sin(t*0.55+3)*65, 0.11, 1.6, 1.1],
    [380+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.7, 0.7],
    [240+Math.cos(t*0.32+5)*125, 210+Math.sin(t*0.5)*85, 0.085, 2.0, 0.9],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.5+1)*50, 0.1, 1.4, 1.2],
    [420+Math.cos(t*0.42+2)*80, 200+Math.sin(t*0.65+4)*60, 0.07, 2.5, 0.65],
    [200+Math.sin(t*0.33+6)*100, 20+Math.cos(t*0.48+5)*70, 0.095, 1.9, 0.85]
  ];
  let aS=0, iS=0, fS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((dx-sX)**2+(dy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    aS+=wave*w; iS+=Math.sin(d*f*0.65+t*sp*0.55+1.5)*w;
    fS+=Math.sin(d*f*1.3-t*sp*0.8+2.8)*w*0.5;
  }
  aS/=6; iS/=6; fS/=4.5;
  const bg=(Math.sin(dx*0.035+dy*0.022+t*0.7)+Math.sin(dx*0.028-dy*0.035+t*1.0))/2
    +Math.sin((dx+dy)*0.11+t*2.3)*0.18+Math.sin((dx-dy)*0.09-t*1.8)*0.18;
  const dist=Math.sqrt((dx-cx)**2+(dy-cy)**2), ang=Math.atan2(dy-cy,dx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t*1.05))*0.35;
  const micro=(Math.sin(dx*0.25+t*1.5)*Math.sin(dy*0.25-t*1.2)
    +Math.sin(dx*0.18-dy*0.18+t*2.0)*0.5)*0.15;
  const laplacian=Math.sin((dx+dy)*0.08+t*0.9)*Math.cos((dx-dy)*0.06-t*0.7)*0.3;
  const reaction=Math.tanh((aS-iS*0.65+bg*0.28+spiral+fS*0.15+micro+laplacian)*2.4);
  const cell=Math.tanh((Math.sin(dx*0.14)*Math.sin(dy*0.14)
    +Math.sin((dx+dy)*0.09+t)*0.45+Math.cos(dx*0.11-dy*0.08-t*0.7)*0.3)*1.6)*0.25;
  const blend=reaction*0.7+cell*0.3, v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,42,88],[18,78,115],[24,125,138],[45,165,140],
    [140,195,110],[210,195,75],[225,145,65],[200,95,72],[165,55,78],
    [110,30,68],[65,18,55],[6,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const pulse=0.85+Math.sin(reaction*Math.PI*1.2)*0.15;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,1-Math.abs(reaction)*1.8)*0.15;
  const lum=pulse*edge+glow;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum+glow*40)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum+glow*25)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum+glow*50)|0
  ];
}
